#!/usr/bin/env bash
# Sync lark-cli's agent skills into an Orange agent workspace.
#
# NOTE: the plugin package now ships `skills/` (generated by build.mjs /
# scripts/package.sh) and Orange copies it into the bound agent workspace on
# startup with write-if-missing semantics. Use this script only for manual
# pushes (e.g. forcing a refresh after upgrading the CLI without deleting the
# workspace copies, or target a workspace Orange does not manage).
#
#   ./scripts/sync-cli-skills.sh                       # main agent, all 28 skills
#   ./scripts/sync-cli-skills.sh --all-agents
#   ./scripts/sync-cli-skills.sh --only lark-shared,lark-doc,lark-drive
#   ./scripts/sync-cli-skills.sh --no-rewrite          # keep bare `lark-cli ...`
#   ./scripts/sync-cli-skills.sh --dry-run
#
# Why a script instead of `cp -R`:
#   1. lark-cli's skills assume the agent can run `lark-cli` in a shell. Orange's
#      shell may run on the host or inside a container, and lark-cli is on PATH
#      in neither. So by default we inject a short adapter block into each
#      SKILL.md telling the model to call the plugin's `lark_cli` tool (which
#      executes the bundled CLI with the right credentials, regardless of where
#      the shell runs).
#      If you prefer real shell execution, pass `--rewrite-path <abs-cli>` to
#      rewrite the command token instead (host shell / bind-mounted container).
#   2. Re-sync must be idempotent and must not delete user-authored skills
#      (feishu-*, flower, pome, ...). Only `lark-*` dirs are managed here.
#   3. A stamp file records which CLI version the copy came from.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ORANGE_HOME="${ORANGE_HOME:-$HOME/.orange}"
SRC="${CLI_SKILLS_DIR:-$ROOT/../../skills}"
CONFIG="$ORANGE_HOME/config.yaml"
BUNDLED_CLI="$ORANGE_HOME/plugins/orange-lark-cli/bin/lark-cli"

AGENTS=()
ALL_AGENTS=0
ONLY=""
PRUNE=0
DRY_RUN=0
FORCE=0
REWRITE=off
ADAPTER=1

while [ $# -gt 0 ]; do
  case "$1" in
    --agent) AGENTS+=("$2"); shift 2 ;;
    --all-agents) ALL_AGENTS=1; shift ;;
    --only) ONLY="$2"; shift 2 ;;
    --prune) PRUNE=1; shift ;;
    --dry-run) DRY_RUN=1; shift ;;
    --force) FORCE=1; shift ;;
    --no-rewrite) REWRITE=off; shift ;;
    --rewrite-path) REWRITE="$2"; ADAPTER=0; shift 2 ;;
    --no-adapter) ADAPTER=0; shift ;;
    --src) SRC="$2"; shift 2 ;;
    -h|--help) sed -n '2,20p' "$0"; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

[ -d "$SRC" ] || { echo "skills source not found: $SRC" >&2; exit 1; }

if [ ${#AGENTS[@]} -eq 0 ]; then
  if [ "$ALL_AGENTS" = "1" ]; then
    while IFS= read -r id; do [ -n "$id" ] && AGENTS+=("$id"); done < <(
      python3 - "$CONFIG" <<'PY'
import sys, yaml
cfg = yaml.safe_load(open(sys.argv[1]))
for a in (cfg.get("agent", {}).get("agents") or []):
    if isinstance(a, dict) and a.get("id"):
        print(a["id"])
PY
    )
  else
    AGENTS=("main")
  fi
fi

if [ "$REWRITE" = "auto" ]; then
  if [ -x "$BUNDLED_CLI" ]; then REWRITE="$BUNDLED_CLI"; else REWRITE=off; fi
fi
if [ "$REWRITE" != "off" ] && [ ! -x "$REWRITE" ]; then
  echo "rewrite target is not executable: $REWRITE" >&2; exit 1
fi

CLI_VERSION="$("$BUNDLED_CLI" --version 2>/dev/null | head -1 || echo unknown)"
SKILLS=()
if [ -n "$ONLY" ]; then
  IFS=',' read -r -a SKILLS <<<"$ONLY"
else
  for d in "$SRC"/lark-*/; do [ -d "$d" ] && SKILLS+=("$(basename "$d")"); done
fi

echo "source   : $SRC"
echo "cli      : ${CLI_VERSION:-unknown}"
echo "rewrite  : $REWRITE"
echo "agents   : ${AGENTS[*]}"
echo "skills   : ${#SKILLS[@]}"
echo

[ "$REWRITE" = "off" ] || export LARK_CLI_ABS="$REWRITE"

for agent in "${AGENTS[@]}"; do
  DEST="$ORANGE_HOME/workspace/$agent/skills"
  echo "== $agent -> $DEST"
  [ "$DRY_RUN" = "1" ] || mkdir -p "$DEST"

  added=0; updated=0; skipped=0
  for skill in "${SKILLS[@]}"; do
    src_dir="$SRC/$skill"
    [ -f "$src_dir/SKILL.md" ] || { echo "  ! skip $skill (no SKILL.md)"; continue; }
    dest_dir="$DEST/$skill"

    if [ -d "$dest_dir" ] && [ "$FORCE" != "1" ] && [ "$DRY_RUN" != "1" ]; then
      if diff -rq "$src_dir" "$dest_dir" >/dev/null 2>&1; then
        skipped=$((skipped + 1)); continue
      fi
      updated=$((updated + 1))
    else
      added=$((added + 1))
    fi

    if [ "$DRY_RUN" = "1" ]; then
      echo "  + would sync $skill"; continue
    fi

    rm -rf "$dest_dir"
    mkdir -p "$dest_dir"
    # -a keeps references/, assets/, starter-components/, routes/, scenes/, scripts/
    cp -a "$src_dir/." "$dest_dir/"

    if [ "$REWRITE" != "off" ]; then
      # Only rewrite the *command token*: `lark-cli <subcommand>` / `lark-cli +foo`.
      # Prose mentions and frontmatter `bins: ["lark-cli"]` stay untouched.
      find "$dest_dir" -type f -name '*.md' -print0 | while IFS= read -r -d '' f; do
        perl -CSD -i -pe 's{(?<![\w./-])lark-cli(?=\s+[a-z+])}{$ENV{LARK_CLI_ABS}}g' "$f"
      done
    fi

    if [ "$ADAPTER" = "1" ]; then
      # Idempotent: strip an older adapter block, then insert right after the
      # YAML frontmatter so the model sees it before any command example.
      python3 - "$dest_dir/SKILL.md" <<'PY'
import re, sys
path = sys.argv[1]
src = open(path, encoding="utf-8").read()
src = re.sub(r"<!-- orange-lark-cli-adapter -->.*?<!-- /orange-lark-cli-adapter -->\n*", "", src, flags=re.S)
block = (
    "<!-- orange-lark-cli-adapter -->\n"
    "> **Orange 运行时（务必先读）**：本技能中出现的 `lark-cli <子命令> ...`，请改用工具 `lark_cli` 执行：\n"
    "> 把 `<子命令>` 及其参数按顺序放入 `argv` 数组，**不要**包含 `lark-cli` 前缀。\n"
    "> 例：`lark-cli docs +create --title 测试文档` → `lark_cli({\"argv\":[\"docs\",\"+create\",\"--title\",\"测试文档\"]})`。\n"
    "> 该工具已内置应用凭证（默认机器人身份）；命令需要用户身份时加 `--as user`。\n"
    "> 若返回 `missing_scopes`，把其中的 `console_url` 转告用户去开通权限，不要盲目重试。\n"
    "<!-- /orange-lark-cli-adapter -->\n"
)
m = re.match(r"^---\n.*?\n---\n", src, flags=re.S)
if m:
    src = src[: m.end()] + "\n" + block + src[m.end():]
else:
    src = block + src
open(path, "w", encoding="utf-8").write(src)
PY
    fi

    echo "  ✓ $skill"
  done

  if [ "$PRUNE" = "1" ] && [ "$DRY_RUN" != "1" ]; then
    for existing in "$DEST"/lark-*/; do
      [ -d "$existing" ] || continue
      name="$(basename "$existing")"
      keep=0
      for s in "${SKILLS[@]}"; do [ "$s" = "$name" ] && keep=1 && break; done
      if [ "$keep" = "0" ]; then rm -rf "$existing"; echo "  - pruned $name"; fi
    done
  fi

  if [ "$DRY_RUN" != "1" ]; then
    python3 - "$DEST/.lark-skills.json" "$SRC" "$CLI_VERSION" "$REWRITE" "$added" "$updated" <<'PY'
import json, sys, datetime
path, src, version, rewrite, added, updated = sys.argv[1:7]
json.dump({
    "source": src,
    "cli_version": version,
    "rewritten_cli_path": None if rewrite == "off" else rewrite,
    "added": int(added),
    "updated": int(updated),
    "synced_at": datetime.datetime.now().astimezone().isoformat(timespec="seconds"),
}, open(path, "w"), ensure_ascii=False, indent=2)
PY
    echo "  added=$added updated=$updated skipped=$skipped"
  fi
done

echo
echo "note: Orange copies <agent-workspace>/skills/* into each session's"
echo "      sandboxes/<agent>/<channel>/.../skills on dispatch (write-if-missing),"
echo "      and mounts that dir as /workspace in the container."
